// Package cli owns command-line parsing and process-facing diagnostics.
package cli

import (
	"flag"
	"fmt"
	"io"
)

// Run parses args and returns the process exit code for csvstat.
func Run(args []string, stdout, stderr io.Writer) int {
	flags := flag.NewFlagSet("csvstat", flag.ContinueOnError)
	flags.SetOutput(stderr)
	if err := flags.Parse(args); err != nil {
		return 2
	}
	if flags.NArg() != 1 {
		_, _ = fmt.Fprintln(stderr, "usage: csvstat FILE")
		return 2
	}

	_, _ = fmt.Fprintln(stdout, "csvstat")
	return 0
}
